<section class="page-heading"><div><p class="eyebrow"><?= e($item['label_name']) ?> · MA GARDE-ROBE</p><h1><?= e($item['name']) ?></h1></div><div class="heading-actions"><a class="button secondary back-button" href="<?= e(url('clothes')) ?>">&larr; Retour</a><a class="button secondary" href="<?= e(url('clothes-edit',['id'=>$item['id']])) ?>">Modifier</a><?php if($item['status']==='archived'): ?><form method="post" action="<?= e(url('clothes-restore')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($item['id']) ?>"><button class="button primary" type="submit">Restaurer</button></form><?php else: ?><form method="post" action="<?= e(url('clothes-delete')) ?>" data-confirm="Archiver cette piece ?"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($item['id']) ?>"><button class="button danger" type="submit">Archiver</button></form><?php endif; ?><form method="post" action="<?= e(url('clothes-delete-permanent')) ?>" data-confirm="Suppression definitive : cette piece, ses photos et ses liens avec les tenues et collections seront supprimes. Cette action est irreversible. Continuer ?"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($item['id']) ?>"><button class="button danger" type="submit">Supprimer definitivement</button></form></div><?php if($item['status']!=='archived'): ?><form method="post" action="<?= e(url('clothing-favorite')) ?>" class="favorite-toggle"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($item['id']) ?>"><button class="button secondary" type="submit">♡ Ajouter ou retirer des favoris</button></form><?php endif; ?></section><section class="detail-layout"><div class="detail-photo"><?php if ($item['image_path']): ?><img src="<?= e(APP_BASE_URL . '/' . $item['image_path']) ?>" alt="<?= e($item['name']) ?>"><?php else: ?><span>GRINGO</span><?php endif; ?></div><div class="detail-panel"><span class="detail-label">DÉTAILS DE LA PIÈCE</span><?php foreach (['brand'=>'Marque','color'=>'Couleur','size'=>'Taille','season'=>'Saison','style'=>'Style','formality'=>'Formalite','occasion'=>'Occasion','purchase_price'=>'Prix d’achat','status'=>'État'] as $field=>$label): if (($item[$field] ?? '') !== '' && $item[$field] !== null): ?><div class="detail-row"><span><?= e($label) ?></span><strong><?= e($field === 'status' ? (['available'=>'Disponible','laundry'=>'Au lavage','repair'=>'À réparer','unavailable'=>'Indisponible','archived'=>'Archivé'][$item[$field]] ?? $item[$field]) : $item[$field] . ($field === 'purchase_price' ? ' ' . $item['currency'] : '')) ?></strong></div><?php endif; endforeach; ?><?php if ($item['description']): ?><div class="detail-copy"><span>Description</span><p><?= nl2br(e($item['description'])) ?></p></div><?php endif; ?><?php if ($item['notes']): ?><div class="detail-copy"><span>Notes</span><p><?= nl2br(e($item['notes'])) ?></p></div><?php endif; ?></div></section>
<?php if(!empty($gallery)): ?><section class="section-head section-spaced"><div><p class="eyebrow">GALERIE</p><h2>Photos supplementaires</h2></div></section><div class="clothes-grid gallery-grid"><?php foreach($gallery as $photo): ?><article class="clothing-card"><img loading="lazy" src="<?= e(APP_BASE_URL.'/'.$photo['image_path']) ?>" alt="Photo de <?= e($item['name']) ?>"><form method="post" action="<?= e(url('clothing-photo-delete')) ?>" data-confirm="Supprimer cette photo ?"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($photo['id']) ?>"><input type="hidden" name="clothing_id" value="<?= e($item['id']) ?>"><button class="button danger">Supprimer la photo</button></form></article><?php endforeach; ?></div><?php endif; ?>
